import { createContext, useContext, useState } from "react";

interface Authinetrface {
  token: string | null;
  role: string | null;
  laoding: boolean;
}

//creating context
const AuthContext = createContext<Authinetrface | undefined>(undefined);

export default function Authcon({ children }: { children: React.ReactNode }) {
  const [token, setToken] = useState<string | null>(null);
  const [role, setRole] = useState<string | null>(null);
  const [loading, setLoadinf] = useState<boolean>(true);

  useState(() => {
    const token = localStorage.getItem("access_token");
    const role = localStorage.getRole("role_key");

    setToken(token);
    setRole(role);
    setLoadinf(false);
  });
  return (
    <AuthContext.Provider value={{ token, role, loading }}>
      {children}
    </AuthContext.Provider>
  );
}
export function UseAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useauth mut be within auth provider");
  }
  return context;
}
